const $=s=>document.querySelector(s),modal=$('#modal');
const PATHS={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',rocket:'m12 3 8 1 1 8-8 8-9-9z M15 9h.01 M6 14l-3 1v6h6l1-3 M9 15l-5 5',chart:'M4 3v18h18 M8 16v-5 M13 16V7 M18 16V4',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M18 8a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.9 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',flag:'M4 22V3 M4 4c6-4 10 4 16 0v10c-6 4-10-4-16 0',layers:'m12 3 10 5-10 5L2 8z M2 12l10 5 10-5 M2 16l10 5 10-5',award:'M8 14 6 22l6-3 6 3-2-8 M19 9A7 7 0 1 1 5 9a7 7 0 0 1 14 0',building:'M4 22V6l8-4 8 4v16 M1 22h22 M8 8h1 M15 8h1 M8 12h1 M15 12h1 M8 16h1 M15 16h1 M10 22v-3h4v3',arrow:'M5 12h14 M13 6l6 6-6 6',up:'M6 18 18 6 M6 6h12v12',check:'m5 12 4 4L19 6',clock:'M12 8v5l3 2 M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',bolt:'m13 2-9 12h7l-1 8 10-13h-7z',bug:'M8 8h8v9a4 4 0 0 1-8 0z M9 8V6a3 3 0 0 1 6 0v2 M3 10h5 M16 10h5 M3 15h5 M16 15h5 M5 21l3-4 M19 21l-3-4',lock:'M5 10h14v12H5z M8 10V6a4 4 0 0 1 8 0v4',play:'m9 4 12 8-12 8z',download:'M12 3v12 m-5-5 5 5 5-5 M4 16v5h16v-5',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',star:'m12 2 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1z',file:'M14 2H5v20h14V7z M14 2v6h5 M8 12h8 M8 16h8',shield:'m12 2 9 4v6c0 6-9 10-9 10S3 18 3 12V6z m-5 10 3 3 7-7',chevron:'m9 5 7 7-7 7',briefcase:'M3 7h18v14H3z M8 7V3h8v4 M3 12l9 3 9-3',message:'M21 3H3v14h5l4 4 4-4h5z M7 8h10 M7 12h7'};
function icon(name,cls=''){return `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${PATHS[name]||PATHS.grid}"/></svg>`;}
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){try{localStorage.setItem('incubyte-product-v3',JSON.stringify(state));return true;}catch{toast('Your browser could not save this change. Export your workspace to keep it.');return false;}}
function logActivity(text){state.activity.unshift({text,date:new Date().toLocaleString()});state.activity=state.activity.slice(0,40);save();}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3600);}
function show(html){$('#modalBody').innerHTML=html;modal.showModal();}
function safeURL(value){try{const u=new URL(value);return ['https:','http:'].includes(u.protocol)?u.href:null;}catch{return null;}}
function project(id=state.selected){return state.projects.find(p=>p.id===id)||state.projects[0];}
function reports(id){return state.reports.filter(r=>r.project===id);}
function accepted(id){return reports(id).filter(r=>r.status==='accepted');}
function gate(p){return accepted(p.id).length>=3&&p.sessions>=5;}
function points(){return state.reports.filter(r=>r.author==='You'&&r.status==='accepted').reduce((s,r)=>s+r.points,0);}
function setProject(id,route){if(!state.projects.some(p=>p.id===id))return;state.selected=id;save();if(route)location.hash=route;render();}
function currentPicker(){return `<select class="project-picker" aria-label="Choose project" onchange="setProject(this.value)">${state.projects.map(p=>`<option value="${esc(p.id)}" ${p.id===project().id?'selected':''}>${esc(p.name)}${p.demo?' · Example':''}</option>`).join('')}</select>`;}
function badge(text,type=''){return `<span class="badge ${type}">${esc(text)}</span>`;}
function pageHead(eyebrow,title,description,extra=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p></div>${extra}</div>`;}
function sampleNote(p=project()){return `<div class="data-note">${icon('shield')}<span>${p.demo?'Example project: all existing metrics and reviews are illustrative.':'Your project: activity shown here comes from this browser.'} New actions are local demonstrations; no external people are contacted.</span></div>`;}
function empty(title,description){return `<div class="empty-state">${icon('layers')}<b>${title}</b><p>${description}</p></div>`;}
function stat(label,value,detail,symbol,color=''){return `<article class="stat-card"><div class="stat-top"><span>${label}</span><span class="stat-icon ${color}">${icon(symbol)}</span></div><strong>${value}</strong><small>${detail}</small></article>`;}
function sparkline(values,color='#457c5a'){const max=Math.max(...values,1);const pts=values.map((v,i)=>`${i*26},${40-v/max*35}`).join(' ');return `<svg class="sparkline" viewBox="0 0 158 45" role="img" aria-label="Seven-day activity trend"><polyline points="${pts}" fill="none" stroke="${color}" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"/></svg>`;}
function projectCard(p){const ready=gate(p);return `<article class="project-card"><div class="project-card-top"><div class="project-monogram ${p.color}">${esc(p.initials)}</div>${badge(p.need,'subtle')}</div><div class="project-category">${esc(p.category)} ${p.demo?'· EXAMPLE':''}</div><h3>${esc(p.name)} <span>${icon('up')}</span></h3><p>${esc(p.description)}</p><div class="project-stats"><span>${icon('people')} <b>${p.sessions}</b> test sessions</span><span>${icon('message')} <b>${accepted(p.id).length}</b> useful reports</span></div><div class="project-card-bottom"><span class="team-id"><i class="${p.color}">${esc(p.team.replace('Team ','').slice(0,2).toUpperCase())}</i>${esc(p.team)}</span><button class="text-button" onclick="openTest('${p.id}')">Test project ${icon('arrow')}</button></div><div class="card-readiness ${ready?'ready':''}">${icon(ready?'check':'clock')}${ready?'Micro-mentorship unlocked':'Building its first validation signals'}</div></article>`;}
function overview(){const total=state.projects.length,validated=state.projects.filter(gate).length,quality=state.reports.filter(r=>r.status==='accepted').length;return `<div class="overview-heading"><div class="eyebrow">WELCOME TO YOUR NEXT CHAPTER</div><span class="quiet-label">Example cohort <span>·</span> Student innovation</span></div><section class="hero"><div class="hero-copy"><span class="hero-label"><i></i> THE STUDENT PROJECT-TO-PRODUCT ECOSYSTEM</span><h1>Built at a hackathon.<br><em>Ready for the real world.</em></h1><p>Give your prototype a real audience. Turn useful feedback into traction, unlock the right mentors, and build toward your first pilot.</p><div class="hero-actions"><button class="button dark" onclick="openProject()">Launch into Betaverse ${icon('up')}</button><a class="button ghost" href="#launchpad">Explore projects ${icon('arrow')}</a></div><div class="hero-footnote"><span class="avatar-stack"><i>M</i><i>A</i><i>Z</i></span><span>A place for builders, testers, and the people who help them grow.</span></div></div><div class="hero-visual" aria-hidden="true"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="orbit-center">${icon('rocket')}</div><div class="float-card float-top"><span class="float-icon">${icon('message')}</span><span>Real feedback.<b>Your next improvement starts here.</b></span><i>↗</i></div><div class="float-card float-bottom"><span class="float-icon lime">${icon('bolt')}</span><span>Traction unlocks possibility.<b>Testing → mentors → your first pilot</b></span></div><div class="floating-dot dot-one"></div><div class="floating-dot dot-two"></div><span class="visual-caption">POTENTIAL, MEET POSSIBILITY.</span></div></section><div class="stats-grid">${stat('Projects in Betaverse',total,'Curated example cohort + your projects','rocket')}${stat('Useful testing reports',quality,'Quality reviewed in this demo','message','orange')}${stat('Mentorship-ready projects',validated,'3 accepted reports + 5 sessions','people','purple')}${stat('Your BytePoints',points()+' <span>BP</span>','Earned through accepted contributions','bolt','yellow')}</div><div class="section-heading"><div><span class="eyebrow">THE INCUBYTE JOURNEY</span><h2>A clear path beyond the prototype.</h2></div><a class="text-button" href="#pipeline">Explore the pipeline ${icon('arrow')}</a></div><section class="journey-strip">${[['rocket','Student project'],['chart','Validation'],['people','Mentorship'],['layers','Improvement'],['flag','Pilot testing'],['briefcase','Funding pathways'],['bolt','Product / startup']].map((s,i)=>`<div class="journey-step ${i===1?'highlight':''}"><span>${icon(s[0])}</span><b>${s[1]}</b><small>0${i+1}</small></div>`).join('')}</section><div class="section-heading"><div><span class="eyebrow">DISCOVER THE BETAVERSE</span><h2>Big ideas. Early chapters.</h2><p>Pick a project. Give it the kind of feedback that moves it forward.</p></div><a class="text-button" href="#launchpad">View all projects ${icon('arrow')}</a></div><div class="project-grid">${state.projects.slice(0,3).map(projectCard).join('')}</div><section class="bottom-invite"><div><span class="eyebrow">GOOD FEEDBACK IS A SKILL.</span><h2>Build products. Build your portfolio.</h2><p>Earn BytePoints for useful testing, track your contributions, and show the impact of your work.</p></div><a class="button dark" href="#portfolio">Your tester portfolio ${icon('up')}</a></section>`;}
function launchpad(){return pageHead('THE BETAVERSE LAUNCHPAD','Good ideas need real users.','Discover student prototypes, complete a focused test, and turn your observations into useful feedback.',`<button class="button dark" onclick="openProject()">＋ Submit your project</button>`)+`<div class="launchpad-banner"><span class="banner-icon">${icon('bolt')}</span><div><b>Useful feedback earns BytePoints.</b><p>Submit a structured bug report or UX review. Points are awarded after a founder rates its usefulness.</p></div><a class="text-button" href="#portfolio">See your portfolio ${icon('arrow')}</a></div><div class="filter-row"><div class="search-field">${icon('search')}<input id="projectSearch" aria-label="Search projects" placeholder="Search projects, teams, or problems…" oninput="filterProjects()"></div><div class="filter-tabs" id="projectCategories">${['All projects','Campus life','Education','Sustainability','Productivity'].map((c,i)=>`<button class="${i===0?'active':''}" data-category="${c}" onclick="filterCategory(this)">${c}</button>`).join('')}</div></div><div class="results-label"><span id="resultCount">${state.projects.length} projects to explore</span><span>Sample ecosystem · local testing demo</span></div><div id="projectGrid" class="project-grid">${state.projects.map(projectCard).join('')}</div>`;}
let projectCategory='All projects';function filterCategory(button){projectCategory=button.dataset.category;document.querySelectorAll('#projectCategories button').forEach(b=>b.classList.toggle('active',b===button));filterProjects();}
function filterProjects(){const q=$('#projectSearch').value.toLowerCase();const list=state.projects.filter(p=>(p.name+' '+p.description+' '+p.team).toLowerCase().includes(q)&&(projectCategory==='All projects'||p.category===projectCategory));$('#projectGrid').innerHTML=list.length?list.map(projectCard).join(''):empty('No projects match yet.','Try another category or search term.');$('#resultCount').textContent=list.length+' projects to explore';}
function openProject(){show(`<div class="eyebrow">YOUR NEXT CHAPTER</div><h2 id="dialogTitle">Launch into Betaverse.</h2><p class="dialog-intro">Give early adopters a clear problem, a prototype, and one focused task.</p><form onsubmit="submitProject(event)"><div class="field-pair"><div><label for="projectName">Project name</label><input id="projectName" name="name" required maxlength="60" placeholder="Your next big idea"></div><div><label for="teamName">Team name</label><input id="teamName" name="team" required maxlength="60" placeholder="The people behind it"></div></div><label for="projectDescription">Who does it help, and how?</label><textarea id="projectDescription" name="description" required maxlength="900" placeholder="Describe the problem and your proposed solution."></textarea><div class="field-pair"><div><label for="projectCategory">Category</label><select id="projectCategory" name="category"><option>Campus life</option><option>Education</option><option>Sustainability</option><option>Productivity</option><option>Other</option></select></div><div><label for="prototypeURL">Prototype link (optional)</label><input id="prototypeURL" name="url" type="url" maxlength="2000" placeholder="https://…"></div></div><label for="testTask">One task for your first testers</label><textarea id="testTask" name="task" required maxlength="600" placeholder="For example: Register for an event and find the attendance check-in action."></textarea><button class="button dark form-submit">Create project ${icon('up')}</button><small class="form-note">Local demo submission. You keep ownership of your project; no public listing is created.</small></form>`);}
function submitProject(e){e.preventDefault();const f=Object.fromEntries(new FormData(e.target));for(const k of ['name','team','description','task']){f[k]=f[k].trim();if(!f[k])return;}if(f.url&&!safeURL(f.url)){toast('Use a valid http or https prototype link.');return;}const p={...f,id:crypto.randomUUID(),initials:f.name[0].toUpperCase(),color:'sage',tagline:f.task,stage:'Testing',sessions:0,returning:0,completion:0,weekly:Array(7).fill(0),retention:Array(7).fill(0),heat:Array(18).fill(0),need:'User feedback',demo:false,goal:f.task};state.projects.unshift(p);state.selected=p.id;logActivity('Launched '+p.name+' into the local Betaverse.');modal.close();location.hash='validation';render();toast('Your project is ready for its first test.');}
function openTest(id){const p=project(id);const url=safeURL(p.url);show(`<div class="eyebrow">BETAVERSE · TEST A PROJECT</div><h2 id="dialogTitle">${esc(p.name)}</h2><p class="dialog-intro">${esc(p.description)}</p><div class="task-box"><span>YOUR TESTING TASK</span><p>${esc(p.task)}</p></div>${url?`<a class="button outline" href="${esc(url)}" target="_blank" rel="noopener noreferrer">Open prototype ${icon('up')}</a>`:'<div class="inline-note">No live prototype is attached. You can explore the report workflow, but do not claim to have tested a real product.</div>'}<div class="report-incentive">${icon('bolt')} Up to 30 BP for an accepted, useful report.</div><form onsubmit="submitReport(event,'${p.id}')"><div class="field-pair"><div><label for="reportType">Contribution type</label><select id="reportType" name="type"><option>UX review</option><option>Bug report</option></select></div><div><label for="experience">Product experience</label><select id="experience" name="experience"><option value="5">5 — Very easy to use</option><option value="4">4 — Mostly easy</option><option value="3" selected>3 — Mixed experience</option><option value="2">2 — Difficult</option><option value="1">1 — Could not complete</option></select></div></div><label for="reportTitle">A specific finding</label><input id="reportTitle" name="title" required maxlength="160" placeholder="What should the team investigate?"><label for="reportSteps">What did you try?</label><textarea id="reportSteps" name="steps" required maxlength="1200" placeholder="Include the steps and context."></textarea><div class="field-pair"><div><label for="reportExpected">What did you expect?</label><textarea id="reportExpected" name="expected" required maxlength="900"></textarea></div><div><label for="reportObserved">What did you observe?</label><textarea id="reportObserved" name="observed" required maxlength="900"></textarea></div></div><label for="reportSuggestion">Suggested improvement</label><textarea id="reportSuggestion" name="suggestion" required maxlength="900" placeholder="What would make the experience better?"></textarea><label class="checkbox-label"><input type="checkbox" name="demo" value="yes" ${!url?'checked':''}>This is an illustrative report, not a live product test.</label><button class="button dark form-submit">Submit for review ${icon('arrow')}</button><small class="form-note">Product experience is your rating. Report usefulness is rated separately by the founder in this local demo.</small></form>`);}
function submitReport(e,id){e.preventDefault();const f=Object.fromEntries(new FormData(e.target));for(const k of ['title','steps','expected','observed','suggestion']){f[k]=f[k].trim();if(!f[k])return;}if(state.reports.some(r=>r.author==='You'&&r.project===id&&r.title.toLowerCase()===f.title.toLowerCase())){toast('You already submitted this finding. Add a different observation.');return;}const p=project(id),demo=f.demo==='yes'||!safeURL(p.url);state.reports.unshift({...f,id:crypto.randomUUID(),project:id,author:'You',initials:'Y',experience:Number(f.experience),quality:0,status:'pending',points:0,demo,date:new Date().toLocaleDateString()});if(!demo&&!state.tested.includes(id)){state.tested.push(id);p.sessions++;p.weekly[6]++;}state.selected=id;logActivity('Submitted '+f.type.toLowerCase()+' for '+p.name+'.');modal.close();location.hash='validation';render();toast('Report saved. Review its usefulness to award BytePoints.');}
function lineChart(values,labels,kind='activity'){const w=610,h=150,pad=18,max=Math.max(...values,1),coords=values.map((v,i)=>[pad+i*(w-pad*2)/6,h-pad-(v/max)*(h-pad*2)]),pts=coords.map(x=>x.join(',')).join(' '),area=`${pad},${h-pad} ${pts} ${w-pad},${h-pad}`;return `<div class="line-chart"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${kind==='retention'?'Sample cohort retention percentage':'Sample daily test sessions'}"><defs><linearGradient id="fill-${kind}" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#8bb18b" stop-opacity=".3"/><stop offset="1" stop-color="#8bb18b" stop-opacity="0"/></linearGradient></defs>${[.25,.5,.75,1].map(v=>`<line x1="${pad}" y1="${h-pad-v*(h-pad*2)}" x2="${w-pad}" y2="${h-pad-v*(h-pad*2)}" stroke="#e9ece4" stroke-dasharray="3 5"/>`).join('')}<polygon points="${area}" fill="url(#fill-${kind})"/><polyline points="${pts}" fill="none" stroke="#4b805b" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>${coords.map((c,i)=>`<circle cx="${c[0]}" cy="${c[1]}" r="3.5" fill="#fff" stroke="#4b805b" stroke-width="2"><title>${labels[i]}: ${values[i]}${kind==='retention'?'%':''}</title></circle>`).join('')}</svg><div class="chart-labels">${labels.map(l=>`<span>${l}</span>`).join('')}</div></div>`;}
function validation(){const p=project(),rs=reports(p.id),ok=accepted(p.id),avg=rs.length?(rs.reduce((s,r)=>s+r.experience,0)/rs.length).toFixed(1):'—';return pageHead('STRUCTURED VALIDATION','Evidence over guesswork.','Understand how people use your prototype and what needs to improve.',currentPicker())+sampleNote(p)+`<div class="stats-grid">${stat('Test sessions',p.sessions,p.demo?'Illustrative example traffic':'Sessions recorded from this browser','people')}${stat('Useful reports',ok.length,rs.filter(r=>r.status==='pending').length+' awaiting a usefulness review','message','orange')}${stat('Returning users',p.demo?p.returning:'—',p.demo?'Illustrative cohort, not live tracking':'Requires multi-user cohort tracking','chart','purple')}${stat('Product experience',avg+(rs.length?' <span>/ 5</span>':''),'Tester-rated · separate from report quality','star','yellow')}</div><div class="validation-layout"><section class="panel chart-panel"><div class="panel-heading"><div><h2>Testing activity</h2><p>${p.demo?'Example daily sessions over seven days':'Local test-session events'}</p></div>${badge('Last 7 days','subtle')}</div>${lineChart(p.weekly,['Day 1','Day 2','Day 3','Day 4','Day 5','Day 6','Day 7'])}</section><section class="panel gate-panel"><div class="panel-heading"><h2>Your next milestone</h2>${icon(gate(p)?'check':'lock')}</div><div class="gate-status ${gate(p)?'unlocked':''}">${gate(p)?'Micro-mentorship unlocked':'Build your validation signals'}</div><p>In this prototype, mentors unlock after two clear milestones.</p>${gateProgress(p)}<button class="button ${gate(p)?'dark':'outline'} full" onclick="setProject('${p.id}','mentorship')">${gate(p)?'Find your next mentor':'Explore the mentorship gate'} ${icon('arrow')}</button></section><section class="panel"><div class="panel-heading"><div><h2>Cohort retention</h2><p>${p.demo?'Illustrative share returning from an example cohort':'No multi-user cohort data yet'}</p></div>${badge(p.demo?'Example data':'Not collected','subtle')}</div>${p.demo?lineChart(p.retention,['D0','D1','D2','D3','D4','D5','D6'],'retention'):empty('Retention starts with a real cohort.','Run a pilot with identifiable, consented participants before reporting retention.')}</section><section class="panel heat-panel"><div class="panel-heading"><div><h2>Interaction map</h2><p>Illustrative click concentrations on a project page</p></div>${badge('Illustration','subtle')}</div><div class="mock-page"><div class="mock-page-bar"><i></i><i></i><i></i><span>Prototype preview</span></div><div class="heatmap-grid">${p.heat.map((v,i)=>`<div class="heat-cell" style="--heat:${v/13}" title="Illustrative cell ${i+1}: intensity ${v}/10">${i===0?'Overview':i===3?'Start task':i===7?'Prototype':i===10?'Feedback':''}</div>`).join('')}</div></div><div class="heat-legend"><span>Low engagement</span><i></i><span>High engagement</span></div><small class="muted">No session recording or live click tracking is installed.</small></section></div><div class="section-heading"><div><span class="eyebrow">CLOSE THE FEEDBACK LOOP</span><h2>Structured feedback, dual ratings.</h2><p>Testers rate the product experience. Founders rate the usefulness of the report.</p></div><button class="button outline" onclick="openTest('${p.id}')">＋ Add a report</button></div><div class="feedback-list">${rs.length?rs.map(reportCard).join(''):empty('Your first useful report starts here.','Invite a tester to try a specific task and record what happened.')}</div>`;}
function gateProgress(p){return `<div class="milestone-check"><span class="check-dot ${accepted(p.id).length>=3?'done':''}">${icon(accepted(p.id).length>=3?'check':'message')}</span><div><b>3 accepted testing reports</b><small>${accepted(p.id).length} / 3 accepted</small></div></div><div class="milestone-check"><span class="check-dot ${p.sessions>=5?'done':''}">${icon(p.sessions>=5?'check':'people')}</span><div><b>5 test sessions</b><small>${p.sessions} / 5 recorded</small></div></div>`;}
function reportCard(r){return `<article class="report-card"><div class="report-header"><span class="person-icon">${esc(r.initials)}</span><div><b>${esc(r.author)}</b><small>${esc(r.date)} ${r.demo?'· Illustrative report':'· Local submission'}</small></div><div class="report-header-tags">${badge(r.type,'subtle')}${badge(r.status==='accepted'?'Accepted':r.status==='revise'?'Needs more detail':'Awaiting review',r.status==='accepted'?'green':'amber')}</div></div><h3>${esc(r.title)}</h3><div class="report-details"><div><b>Steps & context</b><p>${esc(r.steps)}</p></div><div><b>Expected → observed</b><p>${esc(r.expected)} → ${esc(r.observed)}</p></div><div><b>Suggested improvement</b><p>${esc(r.suggestion)}</p></div></div><div class="dual-ratings"><span>${icon('star')} Product experience <b>${r.experience}/5</b></span><span>${icon('message')} Report usefulness <b>${r.quality?r.quality+'/5':'Not rated'}</b></span><span class="earned-points">${r.points?'＋'+r.points+' BP':'Points pending'}</span>${r.status!=='accepted'?`<button class="text-button" onclick="openReportReview('${r.id}')">Review usefulness ${icon('arrow')}</button>`:''}</div></article>`;}
function openReportReview(id){const r=state.reports.find(r=>r.id===id);if(!r||r.status==='accepted')return;show(`<div class="eyebrow">FOUNDER VIEW · LOCAL SIMULATION</div><h2 id="dialogTitle">How useful is this report?</h2><p class="dialog-intro">${esc(r.title)}</p><div class="task-box"><p>${esc(r.suggestion)}</p></div><form onsubmit="reviewReport(event,'${id}')"><label for="qualityRating">Clarity, evidence, and actionability</label><select id="qualityRating" name="quality"><option value="5">5 — Specific, well-supported, actionable · 30 BP</option><option value="4">4 — Clear and useful · 25 BP</option><option value="3">3 — Useful with minor gaps · 15 BP</option><option value="2">2 — Needs more detail · no points yet</option><option value="1">1 — Not actionable yet · no points yet</option></select><label for="qualityNote">Feedback for the tester</label><textarea id="qualityNote" name="note" required maxlength="1000" placeholder="Explain why the finding is useful or what is missing."></textarea><button class="button dark form-submit">Save review ${icon('check')}</button><small class="form-note">You can demonstrate both roles here. This is not independent verification; real deployment requires separate user accounts and moderation.</small></form>`);}
function reviewReport(e,id){e.preventDefault();const r=state.reports.find(r=>r.id===id);if(!r||r.status==='accepted')return;const f=Object.fromEntries(new FormData(e.target)),q=Number(f.quality);if(!Number.isInteger(q)||q<1||q>5||!f.note.trim())return;r.quality=q;r.reviewNote=f.note.trim();r.status=q>=3?'accepted':'revise';r.points=q===5?30:q===4?25:q===3?15:0;logActivity((r.status==='accepted'?'Accepted':'Requested more detail on')+' a report for '+project(r.project).name+'.');modal.close();render();toast(r.status==='accepted'?r.points+' BytePoints awarded to this contributor.':'Review saved. The report needs more detail.');}
function mentorship(){const p=project(),eligible=gate(p),requests=state.mentorRequests.filter(r=>r.project===p.id);return pageHead('MILESTONE-GATED MICRO-MENTORSHIP','The right guidance. At the right time.','A two-minute demo. One focused question. Actionable feedback from a relevant mentor.',currentPicker())+sampleNote(p)+`<section class="mentorship-gate ${eligible?'eligible':''}"><div class="gate-emblem">${icon(eligible?'shield':'lock')}</div><div><span class="eyebrow">${eligible?'YOUR PROJECT HAS INITIAL TRACTION':'VALIDATE BEFORE YOU ACCELERATE'}</span><h2>${eligible?esc(p.name)+' is ready for a mentor.':'Mentorship unlocks with evidence.'}</h2><p>${eligible?'Bring your testing evidence and a focused question. A short review should help you choose the next improvement.':'Complete 3 accepted reports and 5 test sessions. This rule is a prototype policy to demonstrate milestone-gated access.'}</p></div><div class="compact-gate">${gateProgress(p)}</div></section><div class="section-heading"><div><h2>Micro-mentors for your next step.</h2><p>Example profiles, matched by project category and the support needed.</p></div>${badge('Async-first · minimal time commitment','subtle')}</div><div class="mentor-grid">${MENTORS.map(m=>`<article class="mentor-card"><div class="mentor-top"><div class="mentor-avatar ${m.color}">${m.initials}</div>${m.match.includes(p.category)?badge('Category match','green'):badge('Specialist','subtle')}</div><h3>${m.name}</h3><div class="mentor-role">${m.role}</div><p>${m.description}</p><div class="tag-row">${m.tags.map(t=>badge(t,'subtle')).join('')}</div><button class="button ${eligible?'dark':'outline'} full" onclick="openMentorRequest('${m.id}')">${icon(eligible?'play':'lock')}${eligible?'Submit a 2-minute demo':'See unlock requirements'}</button><small class="muted">Fictional profile · no request is sent</small></article>`).join('')}</div><div class="section-heading"><div><h2>Your mentorship thread</h2><p>Keep the question, demo, and follow-up guidance together.</p></div></div>${requests.length?requests.map(r=>`<article class="panel mentor-thread"><div class="panel-heading"><div><h3>${esc(MENTORS.find(m=>m.id===r.mentor)?.name||'Mentor')} · ${esc(p.name)}</h3><p>Prepared request · saved locally</p></div><button class="text-button" onclick="openAnnotation('${r.id}')">Add mentor annotation ${icon('message')}</button></div><p>${esc(r.question)}</p><a class="text-button" href="${esc(safeURL(r.video)||'#')}" target="_blank" rel="noopener noreferrer">Open submitted demo ${icon('play')}</a>${(r.annotations||[]).map(a=>`<div class="annotation"><b>${Math.floor(a.second/60)}:${String(a.second%60).padStart(2,'0')} · Mentor-view note</b><p>${esc(a.note)}</p></div>`).join('')}<small class="form-note">Annotations entered in this prototype are role simulations, not feedback from a real mentor.</small></article>`).join(''):empty('Make your next question a focused one.','Eligible projects can prepare a demo link and a question for a mentor.')}`;}
function openMentorRequest(id){const p=project();if(!gate(p)){show(`<div class="eyebrow">MILESTONE-GATED MENTORSHIP</div><h2 id="dialogTitle">Build your first validation signals.</h2><p class="dialog-intro">${esc(p.name)} needs 3 accepted reports and 5 sessions before a mentor request can be prepared.</p>${gateProgress(p)}<button class="button dark form-submit" onclick="modal.close();location.hash='validation'">Go to validation ${icon('arrow')}</button>`);return;}const m=MENTORS.find(m=>m.id===id);show(`<div class="eyebrow">MICRO-MENTORSHIP · DEMO REQUEST</div><h2 id="dialogTitle">A focused question for ${m.name.split(' ')[0]}.</h2><p class="dialog-intro">Show what you built, what testing revealed, and the decision you need help making.</p><form onsubmit="submitMentor(event,'${id}','${p.id}')"><label for="demoVideo">Demo video link</label><input id="demoVideo" name="video" type="url" required maxlength="2000" placeholder="https://…"><label for="videoSeconds">Video length in seconds (maximum 120)</label><input id="videoSeconds" name="seconds" type="number" min="1" max="120" required value="120"><label for="mentorQuestion">Your question</label><textarea id="mentorQuestion" name="question" required maxlength="1200" placeholder="What should we improve next, based on our testing evidence?"></textarea><button class="button dark form-submit">Prepare request ${icon('arrow')}</button><small class="form-note">The video length is self-reported. No video is uploaded or analysed, and no mentor is contacted.</small></form>`);}
function submitMentor(e,mentor,id){e.preventDefault();const p=project(id),f=Object.fromEntries(new FormData(e.target));if(!gate(p)){toast('Complete the validation milestones first.');return;}if(!safeURL(f.video)||!Number.isInteger(Number(f.seconds))||Number(f.seconds)<1||Number(f.seconds)>120||!f.question.trim()){toast('Provide a valid demo link, a duration up to 120 seconds, and your question.');return;}state.mentorRequests.unshift({...f,id:crypto.randomUUID(),mentor,project:id,annotations:[]});logActivity('Prepared a micro-mentor request for '+p.name+'.');modal.close();render();toast('Demo request prepared. No message was sent.');}
function openAnnotation(id){show(`<div class="eyebrow">MENTOR VIEW · LOCAL SIMULATION</div><h2 id="dialogTitle">Leave a focused annotation.</h2><form onsubmit="saveAnnotation(event,'${id}')"><label for="annotationSecond">Video time in seconds</label><input id="annotationSecond" name="second" type="number" min="0" max="120" value="0" required><label for="annotationNote">What should the team try next?</label><textarea id="annotationNote" name="note" required maxlength="1400"></textarea><button class="button dark form-submit">Save annotation ${icon('check')}</button></form>`);}
function saveAnnotation(e,id){e.preventDefault();const r=state.mentorRequests.find(r=>r.id===id);if(!r)return;const f=Object.fromEntries(new FormData(e.target));if(!Number.isFinite(Number(f.second))||Number(f.second)<0||Number(f.second)>Number(r.seconds)||!f.note.trim()){toast('Use a timestamp within the submitted demo.');return;}r.annotations.push({second:Number(f.second),note:f.note.trim()});logActivity('Added a simulated mentor annotation.');modal.close();render();toast('Annotation saved in your local thread.');}
function pilots(){const p=project(),apps=state.pilotApplications.filter(a=>a.project===p.id);return pageHead('REAL-WORLD PILOT DEPLOYMENTS','A small trial. A meaningful next step.','Connect a validated prototype with a university department or local business for a focused 30-day pilot.',currentPicker())+sampleNote(p)+`<section class="pilot-intro"><div class="pilot-duration"><strong>30</strong><span>DAYS TO LEARN</span></div><div><h2>Define the scope before you start.</h2><p>Agree on one workflow, responsibilities, success criteria, and a stopping point. Evaluate adoption and reliability before expanding.</p></div>${badge(gate(p)?'Validation milestones met':'Validation required',gate(p)?'green':'amber')}</section><div class="section-heading"><div><h2>Find your first deployment partner.</h2><p>Illustrative opportunities to demonstrate the pilot-matching workflow.</p></div></div><div class="project-grid">${PILOTS.map(x=>`<article class="pilot-card"><div class="pilot-icon">${icon('building')}</div><span class="project-category">${x.org.toUpperCase()} · EXAMPLE</span><h3>${x.title}</h3><p>${x.scope}</p><div class="pilot-meta"><span>${icon('clock')}30-day trial</span><span>${icon('people')}${x.slots}</span></div><div class="pilot-measure"><b>WHAT TO MEASURE</b><p>${x.metric}</p></div><button class="button outline full" onclick="openPilot('${x.id}')">Prepare a pilot proposal ${icon('up')}</button></article>`).join('')}</div><div class="section-heading"><div><h2>Your pilot workspace</h2><p>Scope, milestones, and outcomes in one place.</p></div></div>${apps.length?apps.map(a=>`<article class="panel pilot-workspace"><div class="panel-heading"><div><h3>${esc(PILOTS.find(x=>x.id===a.pilot)?.org||'Pilot partner')} · ${esc(p.name)}</h3><p>${esc(a.start)} → ${esc(a.end)} · 30 days</p></div>${badge(a.status,a.status==='Completed simulation'?'green':'subtle')}</div><div class="pilot-workspace-grid"><div><span class="tiny-label">SCOPE</span><p>${esc(a.scope)}</p></div><div><span class="tiny-label">SUCCESS CRITERIA</span><p>${esc(a.metric)}</p></div><div><span class="tiny-label">RESPONSIBILITIES</span><p>${esc(a.responsibilities)}</p></div></div>${a.outcomes?`<div class="outcome-box"><b>Recorded outcomes · self-reported simulation</b><p>${esc(a.outcomes.notes)}</p><span>${a.outcomes.participants} participants · ${a.outcomes.returning} returned</span></div>`:''}<div class="panel-actions">${a.status==='Prepared proposal'?`<button class="button dark small" onclick="startPilot('${a.id}')">Simulate pilot start ${icon('play')}</button>`:a.status==='Active simulation'?`<button class="button dark small" onclick="openPilotOutcomes('${a.id}')">Record pilot outcomes ${icon('check')}</button>`:`<button class="button dark small" onclick="location.hash='pipeline'">Prepare your pitch draft ${icon('arrow')}</button>`}<span class="muted">Local workflow only · no partner agreement or deployment is created.</span></div></article>`).join(''):empty('Your first pilot starts with a clear proposal.','Choose an example opportunity to define the scope and the evidence you want to collect.')}`;}
function openPilot(id){const p=project();if(!gate(p)){show(`<div class="eyebrow">PILOT READINESS</div><h2 id="dialogTitle">Validate before going live.</h2><p class="dialog-intro">Meet the initial testing milestones before preparing a partner trial for ${esc(p.name)}.</p>${gateProgress(p)}<button class="button dark form-submit" onclick="modal.close();location.hash='validation'">View validation ${icon('arrow')}</button>`);return;}const x=PILOTS.find(x=>x.id===id);show(`<div class="eyebrow">30-DAY PILOT · EXAMPLE OPPORTUNITY</div><h2 id="dialogTitle">${x.title}</h2><form onsubmit="submitPilot(event,'${id}','${p.id}')"><label for="pilotScope">Trial scope</label><textarea id="pilotScope" name="scope" required maxlength="1000">${esc(x.scope)}</textarea><label for="pilotMetric">Success criteria</label><textarea id="pilotMetric" name="metric" required maxlength="1000" placeholder="Set a baseline, a target, and how you will collect results.">${esc(x.metric)}</textarea><label for="pilotResponsibilities">Team and partner responsibilities</label><textarea id="pilotResponsibilities" name="responsibilities" required maxlength="1000" placeholder="Who provides access, support, feedback, and the stop/go decision?"></textarea><label for="pilotStart">Proposed start date</label><input id="pilotStart" name="start" type="date" required value="${new Date().toISOString().slice(0,10)}"><button class="button dark form-submit">Save pilot proposal ${icon('arrow')}</button><small class="form-note">This creates a local draft, not an agreement with the example organisation.</small></form>`);}
function submitPilot(e,pilot,id){e.preventDefault();const f=Object.fromEntries(new FormData(e.target));if(!gate(project(id))){toast('Meet the validation milestones first.');return;}if(!f.scope.trim()||!f.metric.trim()||!f.responsibilities.trim())return;const start=new Date(f.start+'T00:00:00Z');if(Number.isNaN(start.getTime()))return;const end=new Date(start);end.setUTCDate(end.getUTCDate()+30);state.pilotApplications.unshift({...f,id:crypto.randomUUID(),pilot,project:id,end:end.toISOString().slice(0,10),status:'Prepared proposal'});logActivity('Prepared a 30-day pilot proposal for '+project(id).name+'.');modal.close();render();toast('Pilot proposal saved locally.');}
function startPilot(id){const a=state.pilotApplications.find(x=>x.id===id);if(!a||a.status!=='Prepared proposal')return;a.status='Active simulation';logActivity('Started a local pilot simulation.');render();toast('Pilot simulation started. No external deployment occurred.');}
function openPilotOutcomes(id){show(`<div class="eyebrow">PILOT OUTCOMES · LOCAL SIMULATION</div><h2 id="dialogTitle">What did the trial teach you?</h2><form onsubmit="savePilotOutcomes(event,'${id}')"><div class="field-pair"><div><label for="participants">Participants</label><input id="participants" name="participants" type="number" min="1" max="100000" required></div><div><label for="returning">Participants who returned</label><input id="returning" name="returning" type="number" min="0" max="100000" required></div></div><label for="outcomes">Results, evidence, and remaining gaps</label><textarea id="outcomes" name="notes" required maxlength="1800" placeholder="Compare the results with the agreed criteria. Explain what worked, what did not, and what is still uncertain."></textarea><label class="checkbox-label"><input type="checkbox" required>I understand these are self-reported demo results, not partner-verified evidence.</label><button class="button dark form-submit">Save outcomes ${icon('check')}</button></form>`);}
function savePilotOutcomes(e,id){e.preventDefault();const a=state.pilotApplications.find(x=>x.id===id);if(!a||a.status!=='Active simulation')return;const f=Object.fromEntries(new FormData(e.target)),participants=Number(f.participants),returning=Number(f.returning);if(!Number.isInteger(participants)||!Number.isInteger(returning)||participants<1||returning<0||returning>participants||!f.notes.trim()){toast('Returning participants cannot exceed the total.');return;}a.outcomes={participants,returning,notes:f.notes.trim()};a.status='Completed simulation';logActivity('Recorded self-reported pilot outcomes.');modal.close();render();toast('Outcomes recorded. Your pitch draft can now include them.');}
function pipeline(){const p=project(),m=state.milestones[p.id]||{},completed=state.pilotApplications.filter(a=>a.project===p.id&&a.outcomes),ready=gate(p);return pageHead('THE STARTUP PIPELINE','Turn your evidence into a next move.','Package what you have learned, clarify the business, and prepare for incubation or commercialisation.',currentPicker())+sampleNote(p)+`<section class="pipeline-track">${[['Student project',true],['Validation',ready],['Mentorship',state.mentorRequests.some(r=>r.project===p.id)],['Improvement',!!m.improvement],['Pilot testing',!!completed.length],['Funding pathway',state.interests.some(x=>x.project===p.id&&x.type==='Incubation')],['Product / startup',false]].map((s,i)=>`<div class="pipeline-node ${s[1]?'complete':''}"><span>${s[1]?icon('check'):String(i+1).padStart(2,'0')}</span><b>${s[0]}</b><small>${s[1]?'Recorded':'Next step'}</small></div>`).join('')}</section><div class="pipeline-grid"><section class="panel"><div class="panel-heading"><div><span class="eyebrow">BUILD WITH WHAT YOU LEARNED</span><h2>Your next improvement</h2></div>${icon('layers')}</div><form onsubmit="saveMilestones(event,'${p.id}')"><label for="improvement">What changed because of user feedback?</label><textarea id="improvement" name="improvement" required maxlength="1600" placeholder="Connect a finding to a concrete improvement.">${esc(m.improvement||'')}</textarea><label for="customer">Who is the potential paying customer?</label><input id="customer" name="customer" maxlength="200" value="${esc(m.customer||'')}" placeholder="For example: a college department or local business"><label for="business">Business model hypothesis</label><textarea id="business" name="business" maxlength="1000" placeholder="Who pays, for what, and what remains to be validated?">${esc(m.business||'')}</textarea><label for="ask">What support do you need next?</label><textarea id="ask" name="ask" maxlength="1000" placeholder="A pilot introduction, technical support, incubation, or funding preparation.">${esc(m.ask||'')}</textarea><button class="button dark form-submit">Save your next steps ${icon('check')}</button></form></section><div><section class="panel pitch-panel"><div class="pitch-icon">${icon('file')}</div><span class="eyebrow">YOUR EVIDENCE, PACKAGED</span><h2>A pitch starts with proof.</h2><p>Generate a six-slide draft from your project, validation signals, improvements, pilot outcomes, and business assumptions.</p><div class="pitch-checks"><span>${icon('check')} Project & problem</span><span>${icon('check')} Testing evidence with source labels</span><span>${icon('check')} Pilot outcomes & next ask</span></div><button class="button dark full" onclick="openPitch('${p.id}')">Preview pitch draft ${icon('up')}</button><button class="button outline full" onclick="downloadPitch('${p.id}')">${icon('download')} Export printable deck</button><small class="muted">Automatically assembled, not independently verified. Review every claim before sharing.</small></section><section class="panel incubator-panel"><span class="eyebrow">INCUBATOR & SEED-FUND PATHWAYS</span><h2>${completed.length?'Ready to prepare an introduction.':'Build toward an introduction.'}</h2><p>Recommended next step: ${completed.length?'prepare an incubation application using your pilot evidence.':'complete a pilot and document what it taught you.'}</p><button class="button outline full" onclick="openIncubation('${p.id}')">${icon(completed.length?'briefcase':'lock')}${completed.length?'Prepare incubation application':'See readiness checklist'}</button><small class="muted">No incubator or investor is contacted automatically.</small></section></div></div>`;}
function saveMilestones(e,id){e.preventDefault();const f=Object.fromEntries(new FormData(e.target));if(!f.improvement.trim())return;state.milestones[id]=f;logActivity('Updated the improvement and business assumptions for '+project(id).name+'.');toast('Next steps saved. Your pitch draft now includes them.');render();}
function deckSlides(id){const p=project(id),m=state.milestones[id]||{},apps=state.pilotApplications.filter(a=>a.project===id&&a.outcomes),own=reports(id).filter(r=>!r.demo).length;return [{title:p.name,sub:'The problem & the people',body:p.description},{title:'The proposed solution',sub:'A focused first version',body:p.task},{title:'Validation signals',sub:p.demo?'Illustrative metrics — example project':'Local browser data — not independently verified',body:`${p.sessions} test sessions; ${accepted(id).length} accepted reports; ${own} non-illustrative report submissions. Product experience: ${reports(id).length?(reports(id).reduce((s,r)=>s+r.experience,0)/reports(id).length).toFixed(1)+'/5':'not yet rated'}. Founder reviews in this prototype are role simulations.`},{title:'What we improved',sub:'Feedback → action',body:m.improvement||'No feedback-based improvement has been recorded yet.'},{title:'Pilot evidence',sub:'Self-reported, not partner-verified',body:apps.length?apps.map(a=>`${a.outcomes.participants} participants; ${a.outcomes.returning} returned. ${a.outcomes.notes}`).join('\n\n'):'No completed pilot has been recorded. The next step is to agree and run a small trial.'},{title:'The next chapter',sub:'Customer, business model & support needed',body:`Potential customer: ${m.customer||'To be validated'}.\nBusiness model: ${m.business||'To be validated'}.\nNext ask: ${m.ask||'Recruit users and a pilot partner.'}`}];}
function openPitch(id){const slides=deckSlides(id);show(`<div class="eyebrow">AUTOMATIC PITCH DRAFT · REVIEW BEFORE SHARING</div><h2 id="dialogTitle">${esc(project(id).name)} · next chapter</h2><div class="deck-preview">${slides.map((s,i)=>`<section class="deck-slide"><span>0${i+1} / 06</span><small>${esc(s.sub)}</small><h3>${esc(s.title)}</h3><p>${esc(s.body)}</p></section>`).join('')}</div><button class="button dark form-submit" onclick="downloadPitch('${id}')">${icon('download')} Export printable deck</button>`);}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function downloadPitch(id){const slides=deckSlides(id);const html=`<!doctype html><html lang="en"><meta charset="utf-8"><title>${esc(project(id).name)} — IncuBYTE pitch draft</title><style>body{margin:0;background:#eef1e8;font:17px system-ui;color:#173f36}section{padding:65px;min-height:450px;margin:30px auto;background:#fff;max-width:950px;box-sizing:border-box;border-top:12px solid #173f36;break-after:page}h1{font-size:42px}p{line-height:1.9;white-space:pre-wrap}small{color:#7d8b73}footer{font-size:12px;color:#7b8475;margin-top:45px}@media print{body{background:#fff}section{margin:0;min-height:94vh}button{display:none}}</style><button onclick="window.print()" style="margin:20px;padding:12px">Print or save as PDF</button>${slides.map((s,i)=>`<section><small>INCU<span>BYTE</span> · PITCH DRAFT · ${i+1}/6</small><h1>${esc(s.title)}</h1><b>${esc(s.sub)}</b><p>${esc(s.body)}</p><footer>Demo-generated draft. Claims and assumptions require review; no independent verification or funding commitment.</footer></section>`).join('')}</html>`;download(project(id).name.replace(/[^a-z0-9]/gi,'-').toLowerCase()+'-incubyte-pitch.html',html,'text/html');toast('Printable pitch draft exported.');}
function openIncubation(id){const p=project(id),completed=state.pilotApplications.some(a=>a.project===id&&a.outcomes);if(!completed){show(`<div class="eyebrow">INCUBATION READINESS</div><h2 id="dialogTitle">Bring evidence to the next conversation.</h2><p class="dialog-intro">Document a completed pilot and its results before preparing an incubation application.</p><button class="button dark form-submit" onclick="modal.close();location.hash='pilots'">Explore pilot opportunities ${icon('arrow')}</button>`);return;}show(`<div class="eyebrow">INCUBATION APPLICATION · LOCAL DRAFT</div><h2 id="dialogTitle">Prepare ${esc(p.name)} for its next step.</h2><form onsubmit="saveInterest(event,'Incubation','${id}')"><label for="incubatorTrack">Support pathway</label><select id="incubatorTrack" name="plan"><option>College incubation cell · example pathway</option><option>Startup incubator · example pathway</option><option>Seed-fund preparation · example pathway</option></select><label for="incubatorNote">What support are you seeking?</label><textarea id="incubatorNote" name="note" required maxlength="1400"></textarea><button class="button dark form-submit">Save application draft ${icon('arrow')}</button><small class="form-note">No real programme, investor, or institution is contacted.</small></form>`);}
function leaderboard(){const authors={};state.reports.filter(r=>r.status==='accepted').forEach(r=>{authors[r.author]??={name:r.author,initials:r.initials,points:0,reports:0,quality:0,demo:r.demo};authors[r.author].points+=r.points;authors[r.author].reports++;authors[r.author].quality+=r.quality;});return Object.values(authors).sort((a,b)=>b.points-a.points);}
function portfolio(){const mine=state.reports.filter(r=>r.author==='You'),good=mine.filter(r=>r.status==='accepted'),bp=points(),level=bp>=150?'Quality catalyst':bp>=75?'Insight builder':bp>=25?'Pathfinder':'First steps',avg=good.length?(good.reduce((s,r)=>s+r.quality,0)/good.length).toFixed(1):'—';return pageHead('TESTER PORTFOLIO BUILDER','Your feedback is a contribution.','Build a record of thoughtful testing, useful insights, and the projects you helped improve.',`<button class="button outline" onclick="exportPortfolio()">${icon('download')} Export portfolio</button>`)+`<section class="portfolio-hero"><div class="portfolio-person"><div class="portfolio-avatar">Y</div><div><span class="eyebrow">YOUR CONTRIBUTOR PROFILE</span><h2>Curiosity, with an impact.</h2><p>UX reviews · Bug reports · Product thinking</p></div></div><div class="points-wallet"><span>YOUR BYTEPOINTS</span><strong>${bp}<small>BP</small></strong><b>${level}</b></div></section><div class="stats-grid">${stat('Reports contributed',mine.length,'Structured submissions in this browser','file')}${stat('Accepted contributions',good.length,'Rated for clarity and usefulness','check','orange')}${stat('Average usefulness',avg+(good.length?' <span>/ 5</span>':''),'Founder-view ratings in this demo','star','purple')}${stat('Projects supported',new Set(mine.map(r=>r.project)).size,'Different student projects reviewed','rocket','yellow')}</div><div class="portfolio-layout"><section class="panel"><div class="panel-heading"><div><h2>Your contribution history</h2><p>A traceable record of what you noticed and how it helped.</p></div></div>${mine.length?mine.map(r=>`<div class="contribution-row"><div class="contribution-icon">${icon(r.type==='Bug report'?'bug':'message')}</div><div><b>${esc(r.title)}</b><small>${esc(project(r.project).name)} · ${esc(r.type)} · ${r.demo?'Illustrative submission':'Local report'}</small></div><span class="contribution-points">${r.status==='accepted'?'+'+r.points+' BP':r.status==='revise'?'Needs detail':'In review'}</span></div>`).join(''):empty('Your first insight is waiting.','Choose a project in Betaverse and submit a clear, actionable report.')}<a class="button outline full" href="#launchpad">Explore projects to test ${icon('arrow')}</a></section><section class="panel"><div class="panel-heading"><div><h2>The ByteBoard</h2><p>Quality-weighted contributions · example community</p></div>${icon('award')}</div><div class="leaderboard">${leaderboard().map((x,i)=>`<div class="leader-row ${x.name==='You'?'is-you':''}"><span class="rank">${String(i+1).padStart(2,'0')}</span><span class="person-icon">${esc(x.initials)}</span><div><b>${esc(x.name)}${x.name==='You'?' · You':''}</b><small>${x.reports} useful reports · ${(x.quality/x.reports).toFixed(1)}/5 quality</small></div><strong>${x.points}<small>BP</small></strong></div>`).join('')}</div><div class="points-explainer">${icon('bolt')}<p><b>Quality earns points.</b><br>Accepted reports earn 15, 25, or 30 BP based on usefulness. There are no cash rewards or purchases in this demo.</p></div></section></div><div class="data-note">${icon('shield')}<span>This portfolio is self-contained demo evidence. A production portfolio would need separate reviewer accounts, anti-abuse controls, and independent verification.</span></div>`;}
function exportPortfolio(){const rows=state.reports.filter(r=>r.author==='You');const text=['# IncuBYTE — Tester portfolio','Prototype export: local, not independently verified',`BytePoints: ${points()}`,`Accepted reports: ${rows.filter(r=>r.status==='accepted').length}`,...rows.map(r=>`## ${r.title}\nProject: ${project(r.project).name}\nType: ${r.type}\nStatus: ${r.status}\nUsefulness: ${r.quality||'Not rated'}/5\nPoints: ${r.points}\nIllustrative: ${r.demo?'Yes':'No (local submission)'}\n\n${r.observed}\n\nSuggested improvement: ${r.suggestion}`)].join('\n\n');download('incubyte-tester-portfolio.md',text,'text/markdown');toast('Your contribution portfolio was exported.');}
let partnerTab='colleges';
function partners(){return pageHead('COLLEGES, ORGANISATIONS & PARTNERS','An ecosystem that grows together.','Support student innovation, discover talent through their work, and create pathways to real adoption.')+`<div class="partner-tabs" role="group" aria-label="Partner offerings">${[['colleges','College dashboard','building'],['talent','Talent scouting','people'],['challenges','Sponsored challenges','flag'],['plans','Plans & services','briefcase']].map(s=>`<button class="${partnerTab===s[0]?'active':''}" onclick="partnerTab='${s[0]}';render()">${icon(s[2])}${s[1]}</button>`).join('')}</div><div id="partnerContent">${partnerTab==='colleges'?collegeDashboard():partnerTab==='talent'?talentScouting():partnerTab==='challenges'?challengeBoard():businessPlans()}</div>`;}
function collegeDashboard(){const ready=state.projects.filter(gate),pilots=state.pilotApplications.length;return `<section class="partner-hero"><div><span class="eyebrow">B2B SAAS · COLLEGE SUBSCRIPTIONS</span><h2>See what happens after the showcase.</h2><p>Track project validation, entrepreneurial activity, pilot progress, and support needs across your student cohort.</p><button class="button dark" onclick="openPlan('College subscription')">Discuss a college plan ${icon('arrow')}</button></div><div class="partner-hero-icon">${icon('building')}</div></section><div class="stats-grid">${stat('Projects tracked',state.projects.length,'Example cohort + local submissions','rocket')}${stat('Initial validation met',ready.length,'Testing milestones achieved','chart','orange')}${stat('Pilot proposals',pilots,'Local prepared or simulated pilots','flag','purple')}${stat('Mentorship requests',state.mentorRequests.length,'Locally prepared demo requests','people','yellow')}</div><section class="panel cohort-table"><div class="panel-heading"><div><h2>Innovation cohort overview</h2><p>Performance signals, progression, and where a team needs help.</p></div><button class="text-button" onclick="exportWorkspace()">Export cohort data ${icon('download')}</button></div><div class="table-scroll"><table><thead><tr><th>Project / team</th><th>Validation</th><th>Useful reports</th><th>Mentorship</th><th>IP / patent potential</th><th></th></tr></thead><tbody>${state.projects.map(p=>`<tr><td><b>${esc(p.name)}</b><small>${esc(p.team)}${p.demo?' · Example':''}</small></td><td>${badge(gate(p)?'Initial traction':'Building evidence',gate(p)?'green':'subtle')}</td><td>${accepted(p.id).length}</td><td>${state.mentorRequests.filter(r=>r.project===p.id).length} prepared</td><td><span class="muted">Not assessed</span></td><td><button class="text-button" onclick="setProject('${p.id}','validation')">View ${icon('up')}</button></td></tr>`).join('')}</tbody></table></div><small class="form-note">Patent potential requires a separate qualified assessment; this platform does not determine patentability.</small></section>`;}
function talentScouting(){return `<section class="partner-hero"><div><span class="eyebrow">ORGANISATIONAL ACCESS · TALENT SCOUTING</span><h2>Discover talent through what they do.</h2><p>Explore project evidence and useful contributions by aspiring developers, product managers, and UX researchers.</p><button class="button dark" onclick="openPlan('Organisational talent access')">Explore organisation access ${icon('arrow')}</button></div><div class="partner-hero-icon">${icon('people')}</div></section><div class="section-heading"><div><h2>Contribution-led talent signals</h2><p>Example profiles ranked by accepted report quality, with a traceable contribution history.</p></div></div><div class="mentor-grid">${leaderboard().map(x=>`<article class="mentor-card"><div class="mentor-avatar sage">${esc(x.initials)}</div><h3>${esc(x.name)}</h3><div class="mentor-role">Product testing & UX feedback</div><div class="talent-metrics"><span><b>${x.reports}</b> useful reports</span><span><b>${(x.quality/x.reports).toFixed(1)}</b> / 5 quality</span><span><b>${x.points}</b> BytePoints</span></div>${badge(x.name==='You'?'Your local contribution profile':'Illustrative profile','subtle')}<button class="button outline full" onclick="openPlan('Talent profile interest: ${esc(x.name)}')">Save scouting interest ${icon('up')}</button></article>`).join('')}</div><div class="data-note">${icon('shield')}<span>No private student data or contact details are exposed. Production talent discovery would require student consent and verified activity.</span></div>`;}
function challengeBoard(){const list=[...CHALLENGES,...(state.challenges||[])];return `<section class="partner-hero"><div><span class="eyebrow">SPONSORED CHALLENGES & PARTNERSHIPS</span><h2>Bring a real problem to student builders.</h2><p>Organisations can define a focused challenge, offer feedback, and help promising prototypes reach a practical pilot.</p><button class="button dark" onclick="openChallenge()">Draft a sponsored challenge ${icon('flag')}</button></div><div class="partner-hero-icon">${icon('flag')}</div></section><div class="section-heading"><div><h2>Challenge board</h2><p>Example briefs and your locally drafted opportunities.</p></div></div><div class="project-grid">${list.map(c=>`<article class="pilot-card"><div class="pilot-icon">${icon('flag')}</div><span class="project-category">${esc(c.category)} · ${c.demo?'EXAMPLE':'LOCAL DRAFT'}</span><h3>${esc(c.title)}</h3><p>${esc(c.description)}</p><small class="muted">${esc(c.org)}</small><button class="button outline full" onclick="openChallengeInterest('${c.id}')">Prepare project interest ${icon('arrow')}</button></article>`).join('')}</div>`;}
function openChallenge(){show(`<div class="eyebrow">SPONSORED CHALLENGE · LOCAL DRAFT</div><h2 id="dialogTitle">A practical problem, clearly defined.</h2><form onsubmit="saveChallenge(event)"><label for="challengeOrg">Organisation</label><input id="challengeOrg" name="org" required maxlength="100"><label for="challengeTitle">Challenge title</label><input id="challengeTitle" name="title" required maxlength="160"><label for="challengeCategory">Focus area</label><input id="challengeCategory" name="category" required maxlength="60" placeholder="For example: sustainability"><label for="challengeDescription">Problem, constraints, and desired outcome</label><textarea id="challengeDescription" name="description" required maxlength="1600"></textarea><button class="button dark form-submit">Save challenge draft ${icon('check')}</button><small class="form-note">Drafting does not publish a challenge, create a sponsorship, or collect a fee.</small></form>`);}
function saveChallenge(e){e.preventDefault();const f=Object.fromEntries(new FormData(e.target));if(Object.values(f).some(v=>!v.trim()))return;state.challenges??=[];state.challenges.unshift({...f,id:crypto.randomUUID(),demo:false});logActivity('Drafted a sponsored challenge.');modal.close();render();toast('Challenge draft added to your local board.');}
function openChallengeInterest(id){const c=[...CHALLENGES,...(state.challenges||[])].find(c=>c.id===id);show(`<div class="eyebrow">PROJECT INTEREST · LOCAL DRAFT</div><h2 id="dialogTitle">${esc(c.title)}</h2><form onsubmit="saveInterest(event,'Challenge','${project().id}')"><input name="plan" type="hidden" value="${esc(c.title)}"><label for="challengeProject">Project</label><select id="challengeProject" name="project">${state.projects.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select><label for="challengeFit">How does your project address this brief?</label><textarea id="challengeFit" name="note" required maxlength="1200"></textarea><button class="button dark form-submit">Save interest ${icon('arrow')}</button><small class="form-note">No organisation is contacted.</small></form>`);}
function businessPlans(){return `<div class="section-heading"><div><span class="eyebrow">MONETISATION STRATEGY</span><h2>Students build. Partners help it scale.</h2><p>Proposed revenue streams from your brief. Prices and commercial terms are not yet set.</p></div></div><div class="plans-grid">${[['College subscription','B2B SAAS','Annual institution subscription','An innovation dashboard for validation, startup progression, mentorship, and entrepreneurial activity.',['Cohort and project tracking','Progress and support needs','Institution-level reporting'],'building'],['Organisation access','TALENT SCOUTING','Organisation subscription','Discover student builders through project performance and quality of real contributions.',['Consent-based talent discovery','Evidence-linked contributions','Project performance signals'],'people'],['Sponsored challenges','PARTNERSHIPS','Challenge hosting & partnership fees','Bring an industry-specific problem to student teams and support practical solutions.',['Focused challenge briefs','Mentor and feedback coordination','Pathways to scoped pilots'],'flag'],['Premium support','SERVICES & SUCCESS FEES','Service subscription / agreed success fee','Additional assistance for founders moving toward incorporation, incubation, and funding readiness.',['Legal-support referrals','Startup and funding preparation','Incubation coordination'],'briefcase']].map((x,i)=>`<article class="plan-card ${i===0?'featured-plan':''}"><div class="plan-icon">${icon(x[5])}</div><span class="project-category">${x[1]}</span><h3>${x[0]}</h3><div class="plan-model">${x[2]}</div><p>${x[3]}</p><ul>${x[4].map(t=>`<li>${icon('check')}${t}</li>`).join('')}</ul><button class="button ${i===0?'dark':'outline'} full" onclick="openPlan('${x[0]}')">Request plan details ${icon('arrow')}</button></article>`).join('')}</div><div class="data-note">${icon('shield')}<span>No payments, subscriptions, legal services, or success-fee arrangements are activated in this prototype. Requests are saved locally for demonstration.</span></div>`;}
function openPlan(plan){show(`<div class="eyebrow">PARTNER INTEREST · LOCAL DRAFT</div><h2 id="dialogTitle">${esc(plan)}</h2><p class="dialog-intro">Describe the support your organisation needs. This saves a local expression of interest.</p><form onsubmit="saveInterest(event,'Partner plan','')"><input name="plan" type="hidden" value="${esc(plan)}"><label for="partnerNote">Your needs and expected scale</label><textarea id="partnerNote" name="note" required maxlength="1400" placeholder="For example: coordinate a cohort of student projects and mentor reviews."></textarea><button class="button dark form-submit">Save interest ${icon('arrow')}</button><small class="form-note">No email is sent, no subscription starts, and no fee is charged.</small></form>`);}
function saveInterest(e,type,id){e.preventDefault();const f=Object.fromEntries(new FormData(e.target));if(!f.note?.trim())return;state.interests.unshift({...f,id:crypto.randomUUID(),type,project:f.project||id,date:new Date().toLocaleDateString()});logActivity('Saved a '+type.toLowerCase()+' draft.');modal.close();render();toast('Interest saved locally. No message was sent.');}
function exportWorkspace(){download('incubyte-workspace.json',JSON.stringify(state,null,2),'application/json');toast('Workspace data exported.');}
function openWorkspaceInfo(){show(`<div class="eyebrow">CAMPUS WORKSPACE</div><h2 id="dialogTitle">A complete incubation journey.</h2><p class="dialog-intro">Explore Betaverse, validation, micro-mentorship, pilots, and the startup pipeline. Existing sample data is illustrative; your new activity is saved in this browser.</p><div class="task-box"><p>This prototype has no shared database, live mentor network, payment processing, or external application delivery. The site’s existing visitor access is preserved.</p></div><button class="button dark form-submit" onclick="exportWorkspace()">${icon('download')} Export your workspace</button>`);}
function openActivity(){show(`<div class="eyebrow">YOUR LOCAL ACTIVITY</div><h2 id="dialogTitle">Your next chapter, in motion.</h2>${state.activity.length?state.activity.map(a=>`<div class="activity-row"><span>${icon('bolt')}</span><div><b>${esc(a.text)}</b><small>${esc(a.date)}</small></div></div>`).join(''):empty('No activity recorded yet.','Launch a project, submit a review, or prepare a pilot to get started.')}<button class="button outline form-submit" onclick="exportWorkspace()">${icon('download')} Export workspace</button>`);}
const ROUTES={overview:{name:'Overview',symbol:'grid',page:overview},launchpad:{name:'Betaverse launchpad',symbol:'rocket',page:launchpad},validation:{name:'Validation dashboard',symbol:'chart',page:validation},mentorship:{name:'Micro-mentorship',symbol:'people',page:mentorship},pilots:{name:'Pilot opportunities',symbol:'flag',page:pilots},pipeline:{name:'Startup pipeline',symbol:'layers',page:pipeline},portfolio:{name:'Tester portfolio',symbol:'award',page:portfolio},partners:{name:'Partners & plans',symbol:'building',page:partners}};
function render(){let route=location.hash.slice(1)||'overview';if(!ROUTES[route])route='overview';if(route==='launchpad')projectCategory='All projects';$('#content').innerHTML=ROUTES[route].page();$('#crumb').textContent=ROUTES[route].name;$('#nav').innerHTML=Object.entries(ROUTES).map(([key,r],i)=>`${i===6?'<div class="nav-label community-label">GROW TOGETHER</div>':''}<a href="#${key}" ${key===route?'aria-current="page"':''} class="${key===route?'active':''}">${icon(r.symbol)}<span>${r.name}</span>${key==='launchpad'?'<i class="nav-new">NEW</i>':''}</a>`).join('');document.title='IncuBYTE — '+ROUTES[route].name;}
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'});});modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close();}});$('.notification-button').innerHTML=icon('bell');render();
